<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores (1934–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;600;700;900&family=Inter:wght@300;400;500;600;700&display=swap');

  :root {
    --bg: #0d0d12;
    --surface: #16161e;
    --surface-2: #1e1e2a;
    --border: #2a2a3a;
    --gold: #c9a84c;
    --gold-light: #e4c76b;
    --gold-dark: #8b6914;
    --text: #e0e0e8;
    --text-muted: #90909c;
    --text-dim: #686878;
    --accent-blue: #5b8cce;
    --accent-teal: #4ea8a0;
    --accent-rose: #c47a8a;
    --accent-purple: #8b7ec8;
    --accent-green: #6aaa6a;
    --kpi-surface: #1a1a28;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    font-family: 'Inter', -apple-system, sans-serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.7;
    font-size: 15px;
    -webkit-font-smoothing: antialiased;
  }

  .container {
    max-width: 1120px;
    margin: 0 auto;
    padding: 0 32px;
  }

  /* ── Hero ─────────────────────────── */
  .hero {
    background: linear-gradient(170deg, #0d0d18 0%, #141428 40%, #0d0d12 100%);
    border-bottom: 1px solid var(--border);
    padding: 80px 0 64px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .hero::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0; bottom: 0;
    background: radial-gradient(ellipse at 50% 0%, rgba(201,168,76,0.08) 0%, transparent 70%);
    pointer-events: none;
  }
  .hero .overline {
    font-family: 'Inter', sans-serif;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 20px;
  }
  .hero h1 {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 3rem;
    font-weight: 900;
    line-height: 1.2;
    color: #f0f0f8;
