  .hero .subtitle {
    font-size: 1.05rem;
    color: var(--text-muted);
    max-width: 620px;
    margin: 0 auto 32px;
    font-weight: 400;
  }
  .hero .meta {
    font-size: 0.8rem;
    color: var(--text-dim);
    letter-spacing: 0.04em;
  }

  /* ── Sections ─────────────────────── */
  section {
    padding: 64px 0;
    border-bottom: 1px solid var(--border);
  }
  section:last-of-type { border-bottom: none; }

  .section-title {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 1.8rem;
    font-weight: 700;
    color: #e8e8f4;
    margin-bottom: 8px;
    letter-spacing: -0.005em;
  }
  .section-overline {
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 6px;
  }
  .section-intro {
    color: var(--text-muted);
    font-size: 0.95rem;
    max-width: 680px;
    margin-bottom: 36px;
    line-height: 1.75;
  }

  /* ── KPI Cards ────────────────────── */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    margin: 40px 0;
  }
  @media (max-width: 860px) { .kpi-grid { grid-template-columns: repeat(2, 1fr); } }
  @media (max-width: 500px) { .kpi-grid { grid-template-columns: 1fr; } }

  .kpi-card {
    background: var(--kpi-surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px;
    text-align: center;
    transition: border-color 0.2s;
  }
  .kpi-card:hover { border-color: var(--gold-dark); }
  .kpi-card .kpi-value {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 2.6rem;
    font-weight: 900;
    color: var(--gold-light);
    line-height: 1.1;
    margin-bottom: 6px;
  }
  .kpi-card .kpi-label {
    font-size: 0.8rem;
    font-weight: 500;
    color: var(--text-muted);
    letter-spacing: 0.03em;
    text-transform: uppercase;
  }
  .kpi-card .kpi-note {
    font-size: 0.72rem;
    color: var(--text-dim);
    margin-top: 4px;
  }

  /* ── Charts ───────────────────────── */
  .chart-container {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px;
    margin: 28px 0;
    position: relative;
  }
  .chart-container canvas { max-height: 420px; }
  .chart-container.tall canvas { max-height: 520px; }
  .chart-title {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 1.15rem;
    font-weight: 600;
    color: #d0d0e0;
    margin-bottom: 4px;
  }
  .chart-subtitle {
    font-size: 0.78rem;
    color: var(--text-dim);
    margin-bottom: 20px;
  }

  /* ── Two-column chart layout ─────── */
  .chart-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
