    width: 100%;
    border-collapse: collapse;
    margin: 28px 0;
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    overflow: hidden;
  }
  .composer-table thead th {
    text-align: left;
    padding: 14px 20px;
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--text-dim);
    background: var(--surface-2);
    border-bottom: 1px solid var(--border);
  }
  .composer-table tbody td {
    padding: 12px 20px;
    font-size: 0.9rem;
    border-bottom: 1px solid rgba(42,42,58,0.5);
    color: var(--text);
  }
  .composer-table tbody tr:last-child td { border-bottom: none; }
  .composer-table .rank {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 1.3rem;
    font-weight: 700;
    color: var(--gold);
  }
  .composer-table .name { font-weight: 600; }
  .composer-table .wins {
    font-weight: 700;
    color: var(--gold-light);
  }
  .composer-table .years { color: var(--text-muted); font-size: 0.82rem; }
  .composer-table .era {
    font-size: 0.72rem;
    font-weight: 500;
    color: var(--text-dim);
    background: var(--surface-2);
    padding: 2px 10px;
    border-radius: 20px;
    white-space: nowrap;
  }

  /* ── Era cards ────────────────────── */
  .era-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin: 28px 0;
  }
  @media (max-width: 700px) { .era-grid { grid-template-columns: 1fr; } }
  .era-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px;
  }
  .era-card .era-header {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin-bottom: 14px;
  }
  .era-card .era-name {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 1.25rem;
    font-weight: 700;
    color: #d8d8e8;
  }
  .era-card .era-years {
    font-size: 0.78rem;
    color: var(--text-dim);
    font-weight: 500;
  }
  .era-card .era-stat {
    display: inline-block;
    font-size: 0.74rem;
    font-weight: 600;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    padding: 3px 10px;
    border-radius: 4px;
    margin-bottom: 12px;
  }
  .era-card .era-stat.golden { background: rgba(201,168,76,0.15); color: var(--gold-light); }
  .era-card .era-stat.silver { background: rgba(91,140,206,0.15); color: var(--accent-blue); }
  .era-card .era-stat.modern { background: rgba(78,168,160,0.15); color: var(--accent-teal); }
  .era-card .era-stat.contemporary { background: rgba(139,126,200,0.15); color: var(--accent-purple); }
  .era-card p { color: var(--text-muted); font-size: 0.88rem; line-height: 1.7; margin-bottom: 10px; }
  .era-card .defining-composers {
    font-size: 0.82rem;
    color: var(--text);
    margin-top: 8px;
  }
  .era-card .defining-composers strong { color: var(--gold-light); font-weight: 600; }

  /* ── Milestones ───────────────────── */
  .milestone-list {
    list-style: none;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 14px;
    margin: 28px 0;
  }
  @media (max-width: 700px) { .milestone-list { grid-template-columns: 1fr; } }
  .milestone-list li {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 20px 22px;
  }
  .milestone-list .milestone-year {
    font-size: 0.72rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    color: var(--gold);
    margin-bottom: 4px;
  }
  .milestone-list .milestone-title {
    font-weight: 600;
    color: #d8d8e8;
    font-size: 0.95rem;
    margin-bottom: 4px;
  }
  .milestone-list .milestone-desc {
    font-size: 0.8rem;
    color: var(--text-muted);
    line-height: 1.5;
  }

  /* ── Takeaways ────────────────────── */
  .takeaway-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 16px;
    margin: 28px 0;
  }
  .takeaway-card {
    background: var(--surface);
    border-left: 3px solid var(--gold);
    border-radius: 0 10px 10px 0;
    padding: 22px 26px;
    border: 1px solid var(--border);
    border-left: 3px solid var(--gold);
  }
  .takeaway-card .takeaway-num {
    font-family: 'Playfair Display', Georgia, serif;
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--gold);
    margin-bottom: 4px;
  }
  .takeaway-card p {
    font-size: 0.92rem;
    color: var(--text-muted);
    line-height: 1.65;
  }
  .takeaway-card p strong { color: var(--text); }

  /* ── Strong text highlight ────────── */
  strong { color: #d0d0e0; }
  .highlight { color: var(--gold-light); font-weight: 600; }

  /* ── Footer ───────────────────────── */
  .report-footer {
    padding: 40px 0;
    text-align: center;
    border-top: 1px solid var(--border);
    font-size: 0.75rem;
    color: var(--text-dim);
  }

  /* ── Paragraph text in sections ───── */
  .prose { max-width: 720px; }
  .prose p { margin-bottom: 16px; color: var(--text-muted); font-size: 0.93rem; line-height: 1.75; }

  /* ── Stat-inline ──────────────────── */
  .stat-inline {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-weight: 600;
    color: var(--gold-light);
  }
